    function transfer(address recipient, uint256 amount) external returns (bool);
    function _maxTxAmount() external view returns (uint256);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x1EB68d088fD07D15b481DbaF219AC2aB61A6c073;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get some QAP tokens for the attacker
        uint256 totalSupply = QAPToken(TARGET).totalSupply();
        deal(TARGET, attacker, 1 * 10**9); // Give attacker 1 token with 9 decimals

        // Label for debugging
        vm.label(TARGET, "QAP Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Directly demonstrate the vulnerability by examining the values
        uint256 maxTxAmount = QAPToken(TARGET)._maxTxAmount();
        uint256 totalSupply = QAPToken(TARGET).totalSupply();

        console.log("=== Transaction Limit Bypass Vulnerability ===");
        console.log("_maxTxAmount (transaction limit):", maxTxAmount);
        console.log("Total supply:", totalSupply);
        console.log("Expected _maxTxAmount (oracle): 5000000000000000000000000000000000");

        // Verify the oracle condition
        assertEq(maxTxAmount, 5000000000000000000000000000000000, "_maxTxAmount should be 5e33 as per oracle");

        // Show that _maxTxAmount is astronomically larger than total supply
        console.log("\nAnalysis:");
        console.log("_maxTxAmount is", maxTxAmount / totalSupply, "times larger than total supply!");

        // Demonstrate that the transaction limit check is ineffective
        // The check in _transfer() is: require(amount <= _maxTxAmount, "Transfer amount exceeds the maxTxAmount.")
        // Since _maxTxAmount is 5e33 and totalSupply is only 1.5e20, ANY transfer up to total supply will pass
        console.log("\nVulnerability Impact:");
        console.log("Any transfer up to the entire total supply (", totalSupply, ") would pass the _maxTxAmount check!");
        console.log("This makes the transaction limit completely ineffective.");

        // Also check numTokensSellToAddToLiquidity which has the same issue
        // We need to read it from storage since it's private
        // Slot calculation: after _tFeeTotal (slot 7), _name (slot 8), _symbol (slot 9), _decimals (slot 10),
        // _taxFee (slot 11), _previousTaxFee (slot 12), _liquidityFee (slot 13), _previousLiquidityFee (slot 14),
        // uniswapV2Router (slot 15), uniswapV2Pair (slot 16), inSwapAndLiquify (slot 17),
        // swapAndLiquifyEnabled (slot 18), _maxTxAmount (slot 19), numTokensSellToAddToLiquidity (slot 20)
        bytes32 numTokensSlot = bytes32(uint256(20));
        bytes32 numTokensValue = vm.load(TARGET, numTokensSlot);
        uint256 numTokensSellToAddToLiquidity = uint256(numTokensValue);

        console.log("\nAdditional Issue:");
        console.log("numTokensSellToAddToLiquidity:", numTokensSellToAddToLiquidity);
        console.log("This is also much larger than total supply, preventing automatic liquidity addition.");

        // Final assertion to prove the vulnerability
        assertGt(maxTxAmount, totalSupply * 10000000000000, "_maxTxAmount should be astronomically larger than total supply");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
